with ins as (insert into public.artist_sound_tags (artist_slug,tag,source_url) select x.s,x.tag,x.u from json_to_recordset('[{"s":"rafiki","tag":"Somewhere between a straight and broken beat","u":"https://es-mx.ra.co/dj/rafikiin/biography"},{"s":"rafiki","tag":"Steely breakbeats and psychedelic effects","u":"https://ra.co/reviews/35687"},{"s":"rafiki","tag":"Broken beat, jungle, breaks and house","u":"https://mixmag.asia/read/rafiki-squidworks-tribute-to-mumbai-suburb-bandra-good-luck-ep-new-releases"}]'::json) as x(s text,tag text,u text) join public.artists a on a.slug=x.s on conflict (artist_slug,tag) do nothing returning 1) select count(*) from ins;